/// VM replay implementations for accessibility bindings.
#[inline]
fn destack_accessibility_action_close_vm_replay(
    binding: &BindingCallContext,
    context: &mut vm::BindingContext<'_>,
    world: RuntimeWorld,
    handle: resource::AccessibilityActionHandle,
) -> RuntimeResult<vm::Word> {
    let result = binding.trace().run_binding(
        ACCESSIBILITY_ACTION_CLOSE,
        binding.replay_payload_for(ACCESSIBILITY_ACTION_CLOSE)?,
        context,
        |context| match world {
            RuntimeWorld::Host => {
                platform_vm::destack_accessibility_action_close(binding, context, handle)
            }
            RuntimeWorld::Simulation => {
                platform_simulation_vm::destack_accessibility_action_close(binding, context, handle)
            }
        },
        |_context, result| {
            if let Ok(()) = result {
                let result_recorded = ();
                let payload = AccessibilityActionCloseReplayRecord {
                    result: Ok(result_recorded),
                };
                return Ok(Some(payload));
            }

            if let Err(error) = result {
                let payload = {
                    let result = Err(TraceError::from(error.as_ref()));
                    AccessibilityActionCloseReplayRecord { result }
                };
                return Ok(Some(payload));
            }

            Ok(None)
        },
        |_context, payload| {
            // replay result
            match payload.result {
                Ok(()) => Ok(()),
                Err(error) => Err(Box::<RuntimeError>::from(error)),
            }
        },
    );
    let result = encode_destack_accessibility_action_close_result(context, result)?;
    Ok(result)
}

#[inline]
fn destack_accessibility_action_open_vm_replay(
    binding: &BindingCallContext,
    context: &mut vm::BindingContext<'_>,
    world: RuntimeWorld,
    window: resource::WindowHandle,
    options: AccessibilityActionOpenOptionsVm,
) -> RuntimeResult<vm::Word> {
    let result = binding.trace().run_binding(
        ACCESSIBILITY_ACTION_OPEN,
        binding.replay_payload_for(ACCESSIBILITY_ACTION_OPEN)?,
        context,
        |context| match world {
            RuntimeWorld::Host => {
                platform_vm::destack_accessibility_action_open(binding, context, window, options)
            }
            RuntimeWorld::Simulation => platform_simulation_vm::destack_accessibility_action_open(
                binding, context, window, options,
            ),
        },
        |_context, result| {
            if let Ok(value) = result {
                let result_value: resource::AccessibilityActionHandle = value.clone();
                let result_recorded = result_value;
                let payload = AccessibilityActionOpenReplayRecord {
                    result: Ok(result_recorded),
                };
                return Ok(Some(payload));
            }

            if let Err(error) = result {
                let payload = {
                    let result = Err(TraceError::from(error.as_ref()));
                    AccessibilityActionOpenReplayRecord { result }
                };
                return Ok(Some(payload));
            }

            Ok(None)
        },
        |_context, payload| {
            // replay result
            match payload.result {
                Ok(value) => {
                    let vm_result = value;
                    Ok(vm_result)
                }
                Err(error) => Err(Box::<RuntimeError>::from(error)),
            }
        },
    );
    let result = encode_destack_accessibility_action_open_result(context, result)?;
    Ok(result)
}

